void *malloc(size_t n)
{
    unsigned long p;
    if (n == 0) n = 1;
    n = (n + 7UL) & ~7UL;
    p = heap_next;
    if (p + n > heap_end) return 0;
    heap_next = p + n;
    return (void *)p;
}

void free(void *p) { (void)p; }

