static void fmt_unsigned(char *buf, unsigned long v, int base, int upper, char **out)
{
    char tmp[40];
    int i = 0;
    if (v == 0) tmp[i++] = '0';
    while (v) {
        int d = v % base;
        tmp[i++] = (char)(d < 10 ? '0' + d : (upper ? 'A' : 'a') + d - 10);
        v /= base;
    }
    while (i) *(*out)++ = tmp[--i];
}

static void fmt_signed(char *buf, long v, int base, int upper, char **out)
{
    if (v < 0) { *(*out)++ = '-'; fmt_unsigned(buf, (unsigned long)(-(v + 1)) + 1UL, base, upper, out); }
    else fmt_unsigned(buf, (unsigned long)v, base, upper, out);
}

static int vformat(char *buf, size_t size, const char *fmt, va_list ap)
{
    char *p = buf;
    char *end = size ? buf + size - 1 : buf;
    int wrote = 0;
    while (*fmt) {
        if (*fmt != '%') {
            if (p < end) *p++ = *fmt;
            wrote++; fmt++; continue;
        }
        fmt++;
        if (*fmt == '%') { if (p < end) *p++ = '%'; wrote++; fmt++; continue; }
        if (*fmt == 'l') fmt++;
        if (*fmt == 'z') fmt++;
        if (*fmt == 'u') {
            unsigned long v = va_arg(ap, unsigned int);
            fmt_unsigned(buf, v, 10, 0, &p); wrote += (int)strlen(p);
            // keep rough count separately below
        }
        fmt++;
    }
    (void)wrote; (void)buf; (void)size;
    if (p < end) *p = 0; else if (size) buf[size-1] = 0;
    return (int)(p - buf);
}

int puts(const char *s)
