static int parse_int(const char **p, int base, int *out) {
    const char *s = *p;
    int neg = 0, v = 0;
    if (base == 0) {
        while (isspace((unsigned char)*s)) s++;
        if (*s == '0' && (s[1] == 'x' || s[1] == 'X')) { base = 16; s += 2; }
