/* Minimal MIPS soft-float helpers for the simple JS VM. Integer-only. */
typedef unsigned int u32;
typedef signed int s32;

typedef struct { u32 lo, hi; } Dbits;

static float bitsf(u32 x) { union { float f; u32 u; } u; u.u = x; return u.f; }
static double bitsd(u32 lo, u32 hi) { union { double d; struct { u32 lo, hi; } u; } u; u.u.lo = lo; u.u.hi = hi; return u.d; }
