static int float_cmp(u32 a, u32 b)
{
    u32 as = a >> 31, bs = b >> 31;
    u32 ae = (a >> 23) & 0xff, be = (b >> 23) & 0xff;
    u32 am = a & 0x7fffff, bm = b & 0x7fffff;
    u32 az = (ae == 0 && am == 0), bz = (be == 0 && bm == 0);
    if (az && bz) return 0;
    if (as != bs) return as ? -1 : 1;
    if (ae != be) return (ae < be) != as ? 1 : -1;
    if (am != bm) return (am < bm) != as ? 1 : -1;
    return 0;
}

static u32 float_pack(u32 sign, s32 exp, u32 mant)
{
    if (mant == 0) return sign << 31;
    while (mant >= 0x1000000u) { mant >>= 1; exp++; }
    while (mant < 0x800000u) { mant <<= 1; exp--; }
    if (exp <= 0) {
        int shift = 1 - exp;
        if (shift > 24) return sign << 31;
        mant = (mant + (1u << (shift - 1))) >> shift;
        if (mant == 0) return sign << 31;
        exp = 0;
    } else if (exp >= 255) {
        return (sign << 31) | 0x7f800000u;
    }
    return (sign << 31) | ((u32)exp << 23) | (mant & 0x7fffffu);
}

static u32 float_add(u32 a, u32 b)
{
    u32 as = a >> 31, bs = b >> 31;
    s32 ae = (a >> 23) & 0xff, be = (b >> 23) & 0xff;
    u32 am = a & 0x7fffff, bm = b & 0x7fffff;
    u32 az = (ae == 0 && am == 0), bz = (be == 0 && bm == 0);
    if (az) return b;
    if (bz) return a;
    if (ae == 0) { while (!(am & 0x800000u)) { am <<= 1; ae--; } ae++; }
    else am |= 0x800000u;
    if (be == 0) { while (!(bm & 0x800000u)) { bm <<= 1; be--; } be++; }
    else bm |= 0x800000u;
    if (ae < be) { u32 t; s32 te; t=am; am=bm; bm=t; te=ae; ae=be; be=te; t=as; as=bs; bs=t; }
    s32 diff = ae - be;
    if (diff > 24) diff = 24;
    bm >>= diff;
    if (as == bs) {
        am += bm;
        return float_pack(as, ae, am);
    } else {
        if (am < bm) { u32 t = am; am = bm; bm = t; as = bs; }
        am -= bm;
        if (am == 0) return 0;
        while (!(am & 0x800000u)) { am <<= 1; ae--; }
        return float_pack(as, ae, am);
    }
}

static u32 float_mul(u32 a, u32 b)
{
    u32 as = a >> 31, bs = b >> 31;
    u32 ae = (a >> 23) & 0xff, be = (b >> 23) & 0xff;
    u32 am = a & 0x7fffff, bm = b & 0x7fffff;
    if ((ae == 0 && am == 0) || (be == 0 && bm == 0)) return 0;
    if (ae == 0) { while (!(am & 0x800000u)) { am <<= 1; ae--; } ae++; } else am |= 0x800000u;
    if (be == 0) { while (!(bm & 0x800000u)) { bm <<= 1; be--; } be++; } else bm |= 0x800000u;
    u32 p = ((u32)(am * bm) + 0x400000u) >> 23;
    s32 e = (s32)(ae + be - 127);
    return float_pack(as ^ bs, e, p);
}

static u32 float_div(u32 a, u32 b)
{
    u32 as = a >> 31, bs = b >> 31;
    u32 ae = (a >> 23) & 0xff, be = (b >> 23) & 0xff;
    u32 am = a & 0x7fffff, bm = b & 0x7fffff;
    if ((be == 0 && bm == 0)) return (as ^ bs) << 31 | 0x7f800000u;
    if (ae == 0 && am == 0) return 0;
    if (ae == 0) { while (!(am & 0x800000u)) { am <<= 1; ae--; } ae++; } else am |= 0x800000u;
    if (be == 0) { while (!(bm & 0x800000u)) { bm <<= 1; be--; } be++; } else bm |= 0x800000u;
    u32 q = 0, rem = am;
    int i;
    for (i = 0; i < 24; i++) {
        rem <<= 1;
        q <<= 1;
        if (rem >= bm) { rem -= bm; q |= 1; }
    }
    s32 e = (s32)(ae - be + 127);
    return float_pack(as ^ bs, e, q);
}

static s32 float_to_int(u32 a)
{
    s32 sign = (a >> 31) ? -1 : 1;
    s32 e = (a >> 23) & 0xff;
    u32 m = a & 0x7fffff;
    if (e == 0 && m == 0) return 0;
    if (e < 127) return 0;
    if (e == 0xff) return sign > 0 ? 0x7fffffff : -0x7fffffff-1;
    u32 mant = m | 0x800000u;
    s32 shift = 23 - (e - 127);
    if (shift >= 0) return sign * (s32)(mant >> shift);
    return sign * (s32)(mant << -shift);
}

static u32 int_to_float(s32 x)
{
    u32 sign = 0, u = (u32)x;
    s32 e = 127 + 23;
    if (x < 0) { sign = 0x80000000u; u = (u32)(-(x + 1)) + 1u; }
    if (u == 0) return 0;
    while (!(u & 0x80000000u)) { u <<= 1; e--; }
    return float_pack(sign, e, u >> 8);
}

static Dbits extend_f(u32 a)
{
    u32 s = a & 0x80000000u;
    u32 e = (a >> 23) & 0xff;
    u32 m = a & 0x7fffff;
    Dbits r;
    if (e == 0 && m == 0) { r.lo = 0; r.hi = s; return r; }
    if (e == 0xff) { r.lo = m << 29; r.hi = s | 0x7ff00000u | (m >> 3); return r; }
    r.lo = m << 29;
    r.hi = s | (((u32)(e + 896)) << 20) | (m >> 3);
    return r;
}

static u32 trunc_d(u32 lo, u32 hi)
{
    u32 s = hi & 0x80000000u;
    s32 e = (hi >> 20) & 0x7ff;
    u32 m = (hi & 0xfffff);
    u32 mant = (m << 3) | (lo >> 29);
    if (e == 0 && m == 0 && lo == 0) return 0;
    if (e == 0x7ff) return s | 0x7f800000u;
    s32 fe = (s32)(e - 1023 + 127);
    return float_pack(s, fe, mant);
}

static int double_cmp(u32 alo, u32 ahi, u32 blo, u32 bhi)
{
    u32 as = ahi >> 31, bs = bhi >> 31;
    u32 ae = (ahi >> 20) & 0x7ff, be = (bhi >> 20) & 0x7ff;
    u32 am = ((ahi & 0xfffff) << 10) | (alo >> 22);
