    if (ae != be) return (ae < be) != as ? 1 : -1;
    if (am != bm) return (am < bm) != as ? 1 : -1;
    return 0;
}

/* Single-precision helpers */
float __addsf3(u32 a, u32 b) { return bitsf(float_add(a, b)); }
float __subsf3(u32 a, u32 b) { return bitsf(float_add(a, b ^ 0x80000000u)); }
float __mulsf3(u32 a, u32 b) { return bitsf(float_mul(a, b)); }
